//! The machine-readable delivery manifest (M6 R6b): `<out_root>/manifest.json`, regenerated by every full `pxl build` and checked by
//! `pxl check`, plus the per-part facts the engine team had to guess (`pxl meta`).
//!
//! The manifest is derived from the parts, never typed: per part the frames in order with origin, size and hardware cells (x, y, slot) or
//! sprites, the palette variant of the dynamic slot, the frame semantics (a distinct drawing or engine-flipped), `repeat`, `compose`,
//! `collision` against the visual size, resident or streamed, and the scenes the part belongs to. Per scene the resolved OBJ palette
//! table with stable palette ids (`<set>/<slot name>`), native colour values, the slot-7 variants with the parts that use them, and the
//! files of cycles and underwater palettes labelled with the scene. A part may carry a `bg` form (`bg_variant`): both forms are listed.
//!
//! The facts that no pixel holds live in `meta.toml` next to the asset (`<part>.meta.toml` next to a plain part), edited with `pxl meta`:
//! ```toml
//! residency = "streamed"                      # resident (default) or streamed
//! bg_variant = "bridge_bg"                    # the BG form of a dual-use object (a part of the project)
//! together = ["open", "closed"]               # frames shown on screen together
//! collision = { w = 128, h = 16, dx = 0, dy = 0 }
//! repeat = { stride = [32, 0], count = 4 }
//! compose = [{ part = "icon", dx = 8, dy = -8 }]
//! [frames.right]
//! semantics = "flip_x"                        # distinct (default), flip_x or flip_y: the engine flips another frame
//! flip_of = "left"
//! origin = [8, 16]                            # overrides the part origin for this frame
//! dropped = true                              # not delivered (with `reason`)
//! [zone_remap.zone_3]                         # use this part in zone_3 with its slots moved: "from" = "to"
//! "4" = 5
//! ```
//! `[delivery]` in pxl.toml: `spec = "export/spec.json"` writes a spec listing from the manifest, `client_spec = "client/spec.json"` is the
//! client's own listing (`{"parts": {"NAME": {"frames": [..]}}}`) that a build checks against the manifest.

use crate::fsutil::PathSlash;
use crate::cells;
use crate::fsutil;
use crate::manifest::{Manifest, PartDecl, Scene};
use crate::model::{Part, PartKind};
use crate::output::{Out, PxlError, Result};
use crate::{pxl, template};
use serde_json::{json, Map, Value};
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

// ------------------------------------------------------------------------------------------------ meta

#[derive(Clone, Debug, Default)]
pub struct FrameMeta {
    pub semantics: String,
    pub flip_of: Option<String>,
    pub origin: Option<(i32, i32)>,
    pub dropped: bool,
    pub reason: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Meta {
    pub residency: Option<String>,
    pub bg_variant: Option<String>,
    pub together: Vec<String>,
    pub collision: Option<(i32, i32, i32, i32)>,
    pub repeat: Option<((i32, i32), u32)>,
    pub compose: Vec<(String, i32, i32)>,
    pub frames: BTreeMap<String, FrameMeta>,
    pub zones: Vec<String>,
    pub remap: BTreeMap<String, BTreeMap<u8, u8>>,
}

pub fn meta_path(part_path: &Path) -> PathBuf {
    if crate::asset::is_asset_file(part_path) {
        part_path.parent().map(|p| p.join("meta.toml")).unwrap_or_else(|| PathBuf::from("meta.toml"))
    } else {
        part_path.with_extension("meta.toml")
    }
}

fn merr(p: &Path, msg: impl Into<String>) -> PxlError {
    PxlError::validation(msg.into()).with_loc(crate::output::Loc::file(p.slash()))
}

fn int_pair(v: &toml::Value) -> Option<(i32, i32)> {
    let a = v.as_array()?;
    if a.len() != 2 {
        return None;
    }
    Some((a[0].as_integer()? as i32, a[1].as_integer()? as i32))
}

pub fn parse_meta(text: &str, path: &Path) -> Result<Meta> {
    let t: toml::Table = text.parse().map_err(|e: toml::de::Error| merr(path, format!("invalid meta TOML: {}", e.message())))?;
    let mut m = Meta::default();
    for (k, v) in &t {
        match k.as_str() {
            "residency" => {
                let s = v.as_str().unwrap_or("");
                if s != "resident" && s != "streamed" {
                    return Err(merr(path, "residency must be \"resident\" or \"streamed\""));
                }
                m.residency = Some(s.to_string());
            }
            "bg_variant" => m.bg_variant = Some(v.as_str().ok_or_else(|| merr(path, "bg_variant must be a part name"))?.to_string()),
            "together" | "zones" => {
                let l: Vec<String> = v.as_array().and_then(|a| a.iter().map(|e| e.as_str().map(String::from)).collect()).ok_or_else(|| merr(path, format!("{} must be a list of names", k)))?;
                if k == "together" {
                    m.together = l
                } else {
                    m.zones = l
                }
            }
            "collision" => {
                let c = v.as_table().ok_or_else(|| merr(path, "collision must be { w = N, h = N, dx = N, dy = N }"))?;
                let g = |n: &str| c.get(n).and_then(|x| x.as_integer()).map(|x| x as i32);
                m.collision = Some((g("w").ok_or_else(|| merr(path, "collision needs w"))?, g("h").ok_or_else(|| merr(path, "collision needs h"))?, g("dx").unwrap_or(0), g("dy").unwrap_or(0)));
            }
            "repeat" => {
                let c = v.as_table().ok_or_else(|| merr(path, "repeat must be { stride = [x, y], count = N }"))?;
                let st = c.get("stride").and_then(int_pair).ok_or_else(|| merr(path, "repeat needs stride = [x, y]"))?;
                let n = c.get("count").and_then(|x| x.as_integer()).filter(|n| *n >= 1).ok_or_else(|| merr(path, "repeat needs count >= 1"))?;
                m.repeat = Some((st, n as u32));
            }
            "compose" => {
                for e in v.as_array().ok_or_else(|| merr(path, "compose must be a list of { part, dx, dy }"))? {
                    let c = e.as_table().ok_or_else(|| merr(path, "compose entries are { part, dx, dy }"))?;
                    let p = c.get("part").and_then(|x| x.as_str()).ok_or_else(|| merr(path, "compose entry needs part"))?;
                    let g = |n: &str| c.get(n).and_then(|x| x.as_integer()).unwrap_or(0) as i32;
                    m.compose.push((p.to_string(), g("dx"), g("dy")));
                }
            }
            "frames" => {
                for (fname, fv) in v.as_table().ok_or_else(|| merr(path, "[frames.NAME] tables"))? {
                    let ft = fv.as_table().ok_or_else(|| merr(path, format!("[frames.{}] must be a table", fname)))?;
                    let mut fm = FrameMeta { semantics: "distinct".into(), ..Default::default() };
                    for (fk, fx) in ft {
                        match fk.as_str() {
                            "semantics" => {
                                let s = fx.as_str().unwrap_or("");
                                if !["distinct", "flip_x", "flip_y"].contains(&s) {
                                    return Err(merr(path, format!("[frames.{}] semantics must be distinct, flip_x or flip_y", fname)));
                                }
                                fm.semantics = s.to_string();
                            }
                            "flip_of" => fm.flip_of = fx.as_str().map(String::from),
                            "origin" => fm.origin = Some(int_pair(fx).ok_or_else(|| merr(path, format!("[frames.{}] origin must be [x, y]", fname)))?),
                            "dropped" => fm.dropped = fx.as_bool().unwrap_or(false),
                            "reason" => fm.reason = fx.as_str().map(String::from),
                            o => return Err(merr(path, format!("[frames.{}]: unknown key '{}'", fname, o)).with_hint("allowed: semantics, flip_of, origin, dropped, reason"))
                        }
                    }
                    if fm.semantics != "distinct" && fm.flip_of.is_none() {
                        return Err(merr(path, format!("[frames.{}]: an engine-flipped frame needs flip_of = \"other frame\"", fname)));
                    }
                    m.frames.insert(fname.clone(), fm);
                }
            }
            "zone_remap" => {
                for (sc, rv) in v.as_table().ok_or_else(|| merr(path, "[zone_remap.SCENE] tables"))? {
                    let mut map = BTreeMap::new();
                    for (from, to) in rv.as_table().ok_or_else(|| merr(path, "zone_remap entries are \"from\" = to"))? {
                        let f: u8 = from.parse().map_err(|_| merr(path, format!("zone_remap slot '{}' is not a number", from)))?;
                        let t = to.as_integer().filter(|n| (0..8).contains(n)).ok_or_else(|| merr(path, "zone_remap targets are slot numbers 0..7"))? as u8;
                        map.insert(f, t);
                    }
                    m.remap.insert(sc.clone(), map);
                }
            }
            o => return Err(merr(path, format!("unknown meta key '{}'", o)).with_hint("allowed: residency, bg_variant, together, zones, collision, repeat, compose, frames, zone_remap")),
        }
    }
    Ok(m)
}

pub fn load_meta(part_path: &Path) -> Result<Meta> {
    let p = meta_path(part_path);
    match std::fs::read_to_string(&p) {
        Ok(t) => parse_meta(&t, &p),
        Err(_) => Ok(Meta::default()),
    }
}

// ------------------------------------------------------------------------------------------------ config

/// Is the manifest written and checked? `[project] manifest = true` in pxl.toml (projects made by `pxl new` have it).
pub fn enabled(m: &Manifest) -> bool {
    crate::project::project_table(&m.path).get("manifest").and_then(|v| v.as_bool()).unwrap_or(false)
}

/// `[delivery]` of pxl.toml.
#[derive(Clone, Debug, Default)]
pub struct DeliveryCfg {
    pub spec: Option<String>,
    pub client_spec: Option<String>,
    pub client_checker: Option<String>,
    pub client_pipeline: Option<String>,
    pub package: Option<String>,
}

pub fn delivery_cfg(m: &Manifest) -> DeliveryCfg {
    let t: Option<toml::Table> = std::fs::read_to_string(&m.path).ok().and_then(|t| t.parse::<toml::Table>().ok()).and_then(|t| t.get("delivery")?.as_table().cloned());
    let g = |k: &str| t.as_ref().and_then(|t| t.get(k)).and_then(|v| v.as_str()).map(String::from);
    DeliveryCfg { spec: g("spec"), client_spec: g("client_spec"), client_checker: g("client_checker"), client_pipeline: g("client_pipeline"), package: g("package") }
}

pub fn out_base(m: &Manifest) -> PathBuf {
    match &m.out_root {
        Some(r) => m.dir.join(r),
        None => m.dir.join("export"),
    }
}

pub fn manifest_file(m: &Manifest) -> PathBuf {
    out_base(m).join("manifest.json")
}

// ------------------------------------------------------------------------------------------------ build

fn hex(c: crate::color::Rgb) -> String {
    crate::color::to_hex(c)
}

fn rgb555(c: crate::color::Rgb) -> u32 {
    ((c.b as u32 >> 3) << 10) | ((c.g as u32 >> 3) << 5) | (c.r as u32 >> 3)
}

fn native_of(prof: &crate::profile::Profile, c: crate::color::Rgb) -> Value {
    match crate::hwexport::native(&prof.export_palette, c, prof) {
        Some(n) => json!(n),
        None if prof.fixed_colours.is_empty() && prof.colour_bits == 5 => json!(rgb555(c)),
        None => Value::Null,
    }
}

fn palette_entry(id: &str, slot: u8, name: &str, colors: &[crate::color::Rgb], prof: &crate::profile::Profile) -> Value {
    json!({"id": id, "slot": slot, "name": name, "colors": colors.iter().map(|c| hex(*c)).collect::<Vec<_>>(), "native": colors.iter().map(|c| native_of(prof, *c)).collect::<Vec<_>>()})
}

/// Stable palette ids of a set: `<set>/<slot name>`; a name used twice in a set gets `#<slot>`.
pub fn palette_ids(set: &cells::PaletteSet) -> BTreeMap<u8, String> {
    let mut count: BTreeMap<&str, usize> = BTreeMap::new();
    for d in set.slots.iter().flatten() {
        *count.entry(d.name.as_str()).or_insert(0) += 1;
    }
    set.slots.iter().flatten().map(|d| (d.slot, if count[d.name.as_str()] > 1 { format!("{}/{}#{}", set.name, d.name, d.slot) } else { format!("{}/{}", set.name, d.name) })).collect()
}

struct PartInfo<'a> {
    decl: &'a PartDecl,
    part: Part,
    meta: Meta,
}

fn frame_files(decl: &PartDecl, part: &Part, outputs: &BTreeSet<String>, frame: &str, layer_names: &[String]) -> Vec<String> {
    let mut want: Vec<String> = vec![decl.spec.file_name(frame, 0, "base")];
    for (i, l) in layer_names.iter().enumerate().skip(1) {
        want.push(decl.spec.file_name(frame, i, l));
    }
    let mut more = Vec::new();
    for w in &want {
        if let Some(stem) = w.strip_suffix(".png") {
            more.push(format!("{}.cells.json", stem));
            more.push(format!("{}_detail.png", stem));
        }
    }
    want.extend(more);
    let _ = part;
    let mut v: Vec<String> = outputs.iter().filter(|o| want.iter().any(|w| Path::new(o).file_name().map_or(false, |n| n.to_string_lossy() == *w))).cloned().collect();
    v.sort();
    v
}

/// The manifest JSON and the problems that make a build fail (a spec frame missing, unknown references, shared files).
pub fn build(m: &Manifest) -> Result<(Value, Vec<String>)> {
    let mut problems: Vec<String> = Vec::new();
    let (sp, _tp) = crate::scene::hardware(m)?;
    let mut infos: Vec<PartInfo> = Vec::new();
    for d in &m.parts {
        let part = match pxl::load(&d.path) {
            Ok(p) => p,
            Err(e) => {
                problems.push(format!("{}: {}", d.name, e.msg));
                continue;
            }
        };
        let meta = match load_meta(&d.path) {
            Ok(x) => x,
            Err(e) => {
                problems.push(format!("{}: {}", d.name, e.msg));
                Meta::default()
            }
        };
        infos.push(PartInfo { decl: d, part, meta });
    }
    let names: BTreeSet<&str> = m.parts.iter().map(|d| d.name.as_str()).collect();
    // scene membership and residency per part
    let mut member: BTreeMap<String, Vec<(String, String, bool)>> = BTreeMap::new();
    for sc in &m.scenes {
        for g in &sc.groups {
            for p in &g.parts {
                for d in crate::cellmem::resolve_parts(m, p) {
                    member.entry(d.name.clone()).or_default().push((sc.name.clone(), g.name.clone(), g.streamed));
                }
            }
        }
    }
    let mut parts_json: Vec<Value> = Vec::new();
    let mut files_seen: BTreeMap<String, String> = BTreeMap::new();
    let mut used_slots: BTreeMap<String, BTreeSet<u8>> = BTreeMap::new();
    for pi in &infos {
        let (d, part, meta) = (pi.decl, &pi.part, &pi.meta);
        let status = crate::status::read(&d.path);
        let outputs: BTreeSet<String> = status.hashes.outputs.keys().cloned().collect();
        let prof = crate::profile::load_for(part, None)?;
        let tpl = template::load_for(part).ok();
        let layer_names: Vec<String> = tpl.as_ref().map(|t| t.layers.iter().map(|l| l.name.clone()).collect()).unwrap_or_default();
        let res = if part.palette_set.is_some() && part.kind == PartKind::Sprite { cells::resolve(part, &prof).ok() } else { None };
        // references in the meta must exist
        for c in &meta.compose {
            if !names.contains(c.0.as_str()) {
                problems.push(format!("{}: compose lists '{}' which is not a part", d.name, c.0));
            }
        }
        if let Some(b) = &meta.bg_variant {
            if !names.contains(b.as_str()) {
                problems.push(format!("{}: bg_variant '{}' is not a part", d.name, b));
            }
        }
        for (f, fm) in &meta.frames {
            if part.frame(f).is_none() {
                problems.push(format!("{}: meta names frame '{}' which the part does not have", d.name, f));
            }
            if let Some(o) = &fm.flip_of {
                if part.frame(o).is_none() {
                    problems.push(format!("{}: frame '{}' is a flip of '{}' which the part does not have", d.name, f, o));
                }
            }
            if let Some(o) = fm.origin {
                if o.0.abs() > 2 * part.size.0 as i32 || o.1.abs() > 2 * part.size.1 as i32 {
                    problems.push(format!("{}: frame '{}' origin {:?} lies far outside the {}x{} canvas: pixels would be dropped", d.name, f, o, part.size.0, part.size.1));
                }
            }
        }
        let mut frames = Vec::new();
        for (fi, f) in part.frames.iter().enumerate() {
            let fm = meta.frames.get(&f.name).cloned().unwrap_or(FrameMeta { semantics: "distinct".into(), ..Default::default() });
            let files = frame_files(d, part, &outputs, &f.name, &layer_names);
            for file in &files {
                if let Some(prev) = files_seen.insert(file.clone(), format!("{}/{}", d.name, f.name)) {
                    if prev != format!("{}/{}", d.name, f.name) {
                        problems.push(format!("{} and {} write the same file {}", prev, format!("{}/{}", d.name, f.name), file));
                    }
                }
            }
            let origin = fm.origin.unwrap_or(part.origin);
            let mut fj = Map::new();
            fj.insert("name".into(), json!(f.name));
            fj.insert("index".into(), json!(fi));
            fj.insert("size".into(), json!([f.grid.w, f.grid.h]));
            fj.insert("origin".into(), json!([origin.0, origin.1]));
            fj.insert("semantics".into(), json!(fm.semantics));
            if let Some(o) = &fm.flip_of {
                fj.insert("flip_of".into(), json!(o));
            }
            fj.insert("dropped".into(), json!(fm.dropped));
            if let Some(r) = &fm.reason {
                fj.insert("reason".into(), json!(r));
            }
            fj.insert("source".into(), json!(f.src));
            fj.insert("files".into(), json!(files));
            // hardware cells (palette-set parts) or sprites (variable sizes)
            if part.kind == PartKind::Sprite {
                if let (Some(res), Some(tpl)) = (&res, &tpl) {
                    match cells::export_frame(part, tpl, res, &prof, fi) {
                        Ok(out) => {
                            let cj: Value = serde_json::from_str(&out.cells_json).unwrap_or(Value::Null);
                            for c in cj.as_array().into_iter().flatten() {
                                for k in ["slot", "slot2"] {
                                    if let Some(sn) = c[k].as_u64() {
                                        used_slots.entry(d.name.clone()).or_default().insert(sn as u8);
                                    }
                                }
                            }
                            fj.insert("cells".into(), cj);
                        }
                        Err(e) => problems.push(format!("{}/{}: {}", d.name, f.name, e.msg)),
                    }
                } else if !prof.sprite_sizes.is_empty() {
                    let pl = crate::sprites::place(&f.grid, &prof.sprite_sizes);
                    fj.insert("sprites".into(), json!(pl.iter().map(|s| json!({"x": s.x - part.origin.0, "y": s.y - part.origin.1, "w": s.w, "h": s.h})).collect::<Vec<_>>()));
                }
            }
            frames.push(Value::Object(fj));
        }
        let zones: Vec<String> = {
            let mut z: BTreeSet<String> = member.get(&d.name).map(|v| v.iter().map(|x| x.0.clone()).collect()).unwrap_or_default();
            z.extend(meta.zones.iter().cloned());
            z.into_iter().collect()
        };
        let streamed = member.get(&d.name).map_or(false, |v| v.iter().any(|x| x.2));
        let residency = meta.residency.clone().unwrap_or_else(|| if streamed { "streamed".into() } else { "resident".into() });
        let vis = part.frames.iter().fold((0usize, 0usize), |a, f| (a.0.max(f.grid.w), a.1.max(f.grid.h)));
        let mut pj = Map::new();
        pj.insert("name".into(), json!(d.name));
        pj.insert("path".into(), json!(d.path.strip_prefix(&m.dir).unwrap_or(&d.path).to_string_lossy().replace('\\', "/")));
        pj.insert("kind".into(), json!(match part.kind { PartKind::Sprite => "sprite", PartKind::Tileset => "tileset", PartKind::Screen => "screen" }));
        pj.insert("tags".into(), json!(d.tags));
        pj.insert("category".into(), json!(part.category));
        pj.insert("palette_set".into(), json!(part.palette_set));
        pj.insert("palette_sets".into(), json!(part.palette_sets()));
        pj.insert("palette_variant".into(), json!(part.variant));
        pj.insert("slots".into(), json!(part.slots));
        pj.insert("slots_used".into(), json!(used_slots.get(&d.name).cloned().unwrap_or_default()));
        pj.insert("origin".into(), json!([part.origin.0, part.origin.1]));
        pj.insert("size".into(), json!([part.size.0, part.size.1]));
        pj.insert("visual".into(), json!({"w": vis.0, "h": vis.1}));
        pj.insert("residency".into(), json!(residency));
        pj.insert("zones".into(), json!(zones));
        pj.insert("together".into(), json!(meta.together));
        pj.insert("frames".into(), Value::Array(frames));
        if let Some((w, h, dx, dy)) = meta.collision {
            pj.insert("collision".into(), json!({"w": w, "h": h, "dx": dx, "dy": dy, "visual_w": vis.0, "visual_h": vis.1, "differs": w as usize != vis.0 || h as usize != vis.1}));
        }
        if let Some((st, n)) = meta.repeat {
            pj.insert("repeat".into(), json!({"stride": [st.0, st.1], "count": n}));
        }
        if !meta.compose.is_empty() {
            pj.insert("compose".into(), json!(meta.compose.iter().map(|c| json!({"part": c.0, "dx": c.1, "dy": c.2})).collect::<Vec<_>>()));
        }
        let mut forms = vec!["sprite"];
        if let Some(b) = &meta.bg_variant {
            forms.push("bg");
            let bgf: Vec<String> = infos.iter().find(|x| &x.decl.name == b).map(|x| x.part.frames.iter().map(|f| f.name.clone()).collect()).unwrap_or_default();
            pj.insert("bg_variant".into(), json!({"part": b, "frames": bgf}));
        }
        pj.insert("forms".into(), json!(forms));
        if !meta.remap.is_empty() {
            pj.insert("zone_remap".into(), json!(meta.remap.iter().map(|(s, r)| (s.clone(), json!(r.iter().map(|(a, b)| (a.to_string(), json!(b))).collect::<Map<String, Value>>()))).collect::<Map<String, Value>>()));
        }
        pj.insert("outputs".into(), json!(outputs.iter().collect::<Vec<_>>()));
        parts_json.push(Value::Object(pj));
    }
    // scenes: resolved palette tables with stable ids
    let mut scenes_json = Vec::new();
    let mut all_palettes: BTreeMap<String, Value> = BTreeMap::new();
    for sc in &m.scenes {
        scenes_json.push(scene_json(m, sc, &sp, &infos, &used_slots, &mut all_palettes, &mut problems));
    }
    // client spec: every listed frame must exist in the manifest
    let cfg = delivery_cfg(m);
    if let Some(cs) = &cfg.client_spec {
        match std::fs::read_to_string(m.dir.join(cs)).ok().and_then(|t| serde_json::from_str::<Value>(&t).ok()) {
            Some(v) => {
                for (pname, pv) in v["parts"].as_object().into_iter().flatten() {
                    let have: BTreeSet<String> = parts_json.iter().find(|p| p["name"] == pname.as_str()).map(|p| p["frames"].as_array().unwrap().iter().filter(|f| f["dropped"] != true).map(|f| f["name"].as_str().unwrap().to_string()).collect()).unwrap_or_default();
                    if !parts_json.iter().any(|p| p["name"] == pname.as_str()) {
                        problems.push(format!("client spec {}: part '{}' is not in the project", cs, pname));
                        continue;
                    }
                    for f in pv["frames"].as_array().into_iter().flatten().filter_map(|x| x.as_str()) {
                        if !have.contains(f) {
                            problems.push(format!("client spec {}: frame {}/{} is not delivered (stale spec, or the frame was dropped)", cs, pname, f));
                        }
                    }
                    for f in &have {
                        if !pv["frames"].as_array().map_or(false, |a| a.iter().any(|x| x.as_str() == Some(f))) {
                            problems.push(format!("client spec {}: frame {}/{} is delivered but the spec does not list it", cs, pname, f));
                        }
                    }
                }
            }
            None => problems.push(format!("client spec {} cannot be read", cs)),
        }
    }
    let console = m.console.clone().unwrap_or_else(|| "gbc".into());
    let v = json!({
        "schema": 1,
        "project": project_name(m),
        "console": console,
        "palette_encoding": palette_encoding(&console, &sp),
        "parts": parts_json,
        "scenes": scenes_json,
        "palettes": all_palettes,
    });
    Ok((v, problems))
}

/// `[project] name`, else the folder name of the project (never empty).
fn project_name(m: &Manifest) -> String {
    let named = crate::project::project_table(&m.path).get("name").and_then(|n| n.as_str()).map(|n| n.trim().to_string()).filter(|n| !n.is_empty());
    named
        .or_else(|| std::fs::canonicalize(&m.dir).ok().and_then(|p| p.file_name().map(|s| s.to_string_lossy().to_string())))
        .filter(|n| !n.is_empty())
        .unwrap_or_else(|| "project".into())
}

/// How a colour is stored for the console (never empty): the console's own export encoding, else the colour model of the profile.
fn palette_encoding(console: &str, sp: &crate::profile::Profile) -> String {
    let e = crate::hwexport::encoding(&sp.export_palette);
    if !e.is_empty() {
        return e.to_string();
    }
    match console {
        "gbc" => "CGB palette word 0BBBBBGGGGGRRRRR (RGB555: blue bits 10-14, green 5-9, red 0-4; value = 8-bit channel / 8); colour 0 of an OBJ palette is transparent".into(),
        _ if sp.colour_bits > 0 => format!("{} bits per channel (value = 8-bit channel / {})", sp.colour_bits, sp.channel_step.max(1)),
        _ if sp.channel_step > 1 => format!("channels in steps of {} (value = 8-bit channel / {})", sp.channel_step, sp.channel_step),
        _ => "8-bit RGB (#rrggbb)".into(),
    }
}

fn scene_json(m: &Manifest, sc: &Scene, sp: &crate::profile::Profile, infos: &[PartInfo], used_slots: &BTreeMap<String, BTreeSet<u8>>, all: &mut BTreeMap<String, Value>, problems: &mut Vec<String>) -> Value {
    let mut palettes = Vec::new();
    let mut variants: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let scene_parts: Vec<&PartInfo> = infos.iter().filter(|pi| sc.groups.iter().any(|g| g.parts.iter().any(|p| crate::cellmem::resolve_parts(m, p).iter().any(|d| d.name == pi.decl.name)))).collect();
    if let Some(sn) = &sc.palette_set {
        match cells::load_set(sn, &m.dir) {
            Ok(set) => {
                let ids = palette_ids(&set);
                for d in set.slots.iter().flatten() {
                    let id = ids[&d.slot].clone();
                    let uses = |pi: &&PartInfo| used_slots.get(&pi.decl.name).map_or(pi.part.slots.is_empty() || pi.part.slots.contains(&d.slot), |u| u.contains(&d.slot));
                    let used: Vec<String> = scene_parts.iter().filter(|pi| uses(pi)).map(|pi| pi.decl.name.clone()).collect();
                    let mut e = if d.colors.is_empty() { json!({"id": id, "slot": d.slot, "name": d.name, "colors": [], "native": []}) } else { palette_entry(&id, d.slot, &d.name, &d.colors, sp) };
                    e["used_by"] = json!(used);
                    if !d.variants.is_empty() {
                        let mut vs = Map::new();
                        for (vn, cs) in &d.variants {
                            let users: Vec<String> = scene_parts.iter().filter(|pi| pi.part.variant.as_deref() == Some(vn.as_str()) && uses(pi)).map(|pi| pi.decl.name.clone()).collect();
                            vs.insert(vn.clone(), json!({"id": format!("{}@{}", id, vn), "colors": cs.iter().map(|c| hex(*c)).collect::<Vec<_>>(), "native": cs.iter().map(|c| native_of(sp, *c)).collect::<Vec<_>>(), "used_by": users}));
                            variants.entry(vn.clone()).or_default();
                            let _ = users;
                        }
                        e["variants"] = Value::Object(vs);
                    }
                    all.insert(id.clone(), e.clone());
                    palettes.push(e);
                }
                // a part with a variant the dynamic slot does not define
                for pi in &scene_parts {
                    if let Some(v) = &pi.part.variant {
                        if !set.slots.iter().flatten().any(|d| d.variants.contains_key(v)) {
                            problems.push(format!("scene {}: {} uses palette variant '{}' that set '{}' does not define", sc.name, pi.decl.name, v, sn));
                        }
                    }
                }
            }
            Err(e) => problems.push(format!("scene {}: {}", sc.name, e.msg)),
        }
    }
    // cycles and underwater palettes of the tile set, labelled with the scene
    for pi in &scene_parts {
        if let Some(v) = &pi.part.variant {
            variants.entry(v.clone()).or_default().push(pi.decl.name.clone());
        }
    }
    let mut cycles = Vec::new();
    let mut bg = Value::Null;
    if let Some(ts) = &sc.tileset {
        if let Some(pi) = infos.iter().find(|pi| &pi.decl.name == ts) {
            let outs: Vec<String> = crate::status::read(&pi.decl.path).hashes.outputs.keys().cloned().collect();
            for o in &outs {
                if o.contains("palette_cycle/") || o.contains("underwater") {
                    cycles.push(json!({"file": o, "scene": sc.name, "kind": if o.contains("underwater") { "underwater" } else { "cycle" }, "palette": pi.part.cycles.iter().filter_map(|c| c.palette.clone()).collect::<Vec<_>>()}));
                }
            }
            bg = json!({"tileset": ts, "palette": pi.part.bg_palette, "files": outs.iter().filter(|o| !o.ends_with(".aseprite")).collect::<Vec<_>>()});
        }
    }
    let mut vj = Map::new();
    for (k, mut v) in variants {
        v.sort();
        v.dedup();
        vj.insert(k, json!(v));
    }
    json!({
        "name": sc.name, "palette_set": sc.palette_set, "tileset": sc.tileset,
        "obj_palettes": palettes, "palette_variants": Value::Object(vj), "bg": bg, "cycles": cycles,
        "groups": sc.groups.iter().map(|g| json!({"name": g.name, "streamed": g.streamed, "budget": g.budget, "per_frame": g.per_frame, "parts": g.parts})).collect::<Vec<_>>(),
        "layout": crate::layout::layout_of(m, sc),
    })
}

/// A spec listing generated from the manifest: part -> frames and files.
pub fn spec_json(man: &Value) -> Value {
    let mut parts = Map::new();
    for p in man["parts"].as_array().into_iter().flatten() {
        let frames: Vec<&Value> = p["frames"].as_array().into_iter().flatten().filter(|f| f["dropped"] != true).collect();
        parts.insert(
            p["name"].as_str().unwrap_or("").to_string(),
            json!({"frames": frames.iter().map(|f| f["name"].clone()).collect::<Vec<_>>(), "files": frames.iter().flat_map(|f| f["files"].as_array().cloned().unwrap_or_default()).collect::<Vec<_>>(), "origin": p["origin"], "size": p["size"]}),
        );
    }
    json!({"schema": 1, "generated_from": "manifest.json", "parts": parts})
}

fn pretty(v: &Value) -> Vec<u8> {
    (serde_json::to_string_pretty(v).unwrap_or_default() + "\n").into_bytes()
}

/// Regenerate `manifest.json` (and the configured spec). Returns the files written and the problems (a build fails on them).
pub fn write(m: &Manifest) -> Result<(Vec<PathBuf>, Vec<String>)> {
    let (v, problems) = build(m)?;
    if !problems.is_empty() {
        return Ok((Vec::new(), problems));
    }
    let mut files = Vec::new();
    let f = manifest_file(m);
    crate::export::write_if_changed(&f, &pretty(&v))?;
    files.push(f);
    if let Some(s) = delivery_cfg(m).spec {
        let sf = m.dir.join(s);
        crate::export::write_if_changed(&sf, &pretty(&spec_json(&v)))?;
        files.push(sf);
    }
    Ok((files, problems))
}

/// What `pxl check` reports: the manifest is missing, stale, or the generated spec is.
pub fn stale(m: &Manifest) -> Vec<String> {
    let mut v = Vec::new();
    let (man, problems) = match build(m) {
        Ok(x) => x,
        Err(e) => return vec![format!("manifest: {}", e.msg)],
    };
    v.extend(problems.into_iter().map(|p| format!("manifest: {}", p)));
    let f = manifest_file(m);
    match std::fs::read(&f) {
        Ok(have) if have == pretty(&man) => {}
        Ok(_) => v.push(format!("manifest: {} is out of date (run `pxl build`)", f.slash())),
        Err(_) => v.push(format!("manifest: {} is missing (run `pxl build`)", f.slash())),
    }
    if let Some(s) = delivery_cfg(m).spec {
        let sf = m.dir.join(&s);
        match std::fs::read(&sf) {
            Ok(have) if have == pretty(&spec_json(&man)) => {}
            Ok(_) => v.push(format!("manifest: spec {} lists frames that differ from the manifest (run `pxl build`)", sf.slash())),
            Err(_) => v.push(format!("manifest: spec {} is missing (run `pxl build`)", sf.slash())),
        }
    }
    v
}

// ------------------------------------------------------------------------------------------------ pxl meta

fn asset_arg(asset: &str) -> Result<PathBuf> {
    fsutil::resolve_part(asset)
}

fn load_table(p: &Path) -> toml::Table {
    std::fs::read_to_string(p).ok().and_then(|t| t.parse::<toml::Table>().ok()).unwrap_or_default()
}

fn save_table(p: &Path, t: &toml::Table, out: &mut Out) -> Result<()> {
    let text = format!("# facts about this asset that no pixel holds (pxl meta); read by the delivery manifest\n{}", toml::to_string_pretty(t).unwrap_or_default());
    parse_meta(&text, p)?; // never write what the manifest cannot read
    fsutil::atomic_write_plain(p, text.as_bytes())?;
    let _ = out;
    Ok(())
}

fn pair_arg(s: &str) -> Option<(i64, i64)> {
    let (a, b) = s.split_once(|c| c == ',' || c == 'x')?;
    Some((a.trim().parse().ok()?, b.trim().parse().ok()?))
}

/// `pxl meta ASSET show | set KEY VALUE... | compose add PART DX DY | compose clear | frame NAME KEY VALUE | zone-remap SCENE a=b,..`
pub fn run_meta(a: &crate::cli::MetaArgs, out: &mut Out) -> Result<()> {
    let path = asset_arg(&a.asset)?;
    let mp = meta_path(&path);
    let usage = |s: &str| PxlError::usage(s.to_string());
    let w: Vec<&str> = a.words.iter().map(|s| s.as_str()).collect();
    if w.first().map_or(true, |x| *x == "show") {
        let m = load_meta(&path)?;
        let t = load_table(&mp);
        out.emit(if t.is_empty() { format!("{}: no meta yet", a.asset) } else { toml::to_string_pretty(&t).unwrap_or_default().trim_end().to_string() }, json!({"meta": serde_json::to_value(&t).unwrap_or(Value::Null), "file": mp.slash(), "ok": m.frames.len() < usize::MAX}));
        return Ok(());
    }
    crate::lease::guard(&path, out.agent())?;
    let mut t = load_table(&mp);
    let sub = |t: &mut toml::Table, k: &str| -> toml::Table { t.get(k).and_then(|v| v.as_table().cloned()).unwrap_or_default() };
    match w.as_slice() {
        ["set", "category", v] => {
            return crate::manedit::set_category(&a.asset, v, out);
        }
        ["set", "collision", v] => {
            let (wd, ht) = pair_arg(v.split('@').next().unwrap_or("")).ok_or_else(|| usage("collision is WxH or WxH@dx,dy"))?;
            let (dx, dy) = v.split_once('@').and_then(|x| pair_arg(x.1)).unwrap_or((0, 0));
            let mut c = toml::Table::new();
            for (k, x) in [("w", wd), ("h", ht), ("dx", dx), ("dy", dy)] {
                c.insert(k.into(), toml::Value::Integer(x));
            }
            t.insert("collision".into(), toml::Value::Table(c));
        }
        ["set", "repeat", stride, count] => {
            let (sx, sy) = pair_arg(stride.trim_start_matches("stride=")).ok_or_else(|| usage("repeat: stride=X,Y count=N"))?;
            let n: i64 = count.trim_start_matches("count=").parse().map_err(|_| usage("repeat: stride=X,Y count=N"))?;
            let mut c = toml::Table::new();
            c.insert("stride".into(), toml::Value::Array(vec![toml::Value::Integer(sx), toml::Value::Integer(sy)]));
            c.insert("count".into(), toml::Value::Integer(n));
            t.insert("repeat".into(), toml::Value::Table(c));
        }
        ["set", k @ ("residency" | "bg_variant"), v] => {
            t.insert(k.to_string(), toml::Value::String(v.to_string()));
        }
        ["set", k @ ("together" | "zones"), vs @ ..] if !vs.is_empty() => {
            t.insert(k.to_string(), toml::Value::Array(vs.iter().map(|x| toml::Value::String(x.to_string())).collect()));
        }
        ["compose", "add", part, dx, dy] => {
            let mut l = t.get("compose").and_then(|v| v.as_array().cloned()).unwrap_or_default();
            let mut c = toml::Table::new();
            c.insert("part".into(), toml::Value::String(part.to_string()));
            c.insert("dx".into(), toml::Value::Integer(dx.parse().map_err(|_| usage("compose add PART DX DY"))?));
            c.insert("dy".into(), toml::Value::Integer(dy.parse().map_err(|_| usage("compose add PART DX DY"))?));
            l.push(toml::Value::Table(c));
            t.insert("compose".into(), toml::Value::Array(l));
        }
        ["compose", "clear"] => {
            t.remove("compose");
        }
        ["frame", name, key, val] => {
            let mut fr = sub(&mut t, "frames");
            let mut f = fr.get(*name).and_then(|v| v.as_table().cloned()).unwrap_or_default();
            match *key {
                "semantics" => {
                    f.insert("semantics".into(), toml::Value::String(val.to_string()));
                    if let Some(o) = &a.of {
                        f.insert("flip_of".into(), toml::Value::String(o.clone()));
                    }
                }
                "origin" => {
                    let (x, y) = pair_arg(val).ok_or_else(|| usage("origin is X,Y"))?;
                    f.insert("origin".into(), toml::Value::Array(vec![toml::Value::Integer(x), toml::Value::Integer(y)]));
                }
                "dropped" => {
                    f.insert("dropped".into(), toml::Value::Boolean(*val == "true"));
                    if let Some(r) = &a.reason {
                        f.insert("reason".into(), toml::Value::String(r.clone()));
                    }
                }
                _ => return Err(usage("frame keys: semantics (with --of FRAME), origin, dropped (with --reason)")),
            }
            fr.insert(name.to_string(), toml::Value::Table(f));
            t.insert("frames".into(), toml::Value::Table(fr));
        }
        ["zone-remap", scene, pairs] => {
            let mut zr = sub(&mut t, "zone_remap");
            let mut e = toml::Table::new();
            for p in pairs.split(',') {
                let (f, to) = p.split_once('=').ok_or_else(|| usage("zone-remap SCENE 4=5,5=4"))?;
                e.insert(f.trim().to_string(), toml::Value::Integer(to.trim().parse().map_err(|_| usage("zone-remap targets are numbers"))?));
            }
            zr.insert(scene.to_string(), toml::Value::Table(e));
            t.insert("zone_remap".into(), toml::Value::Table(zr));
        }
        _ => return Err(usage("pxl meta ASSET show | set category player | set collision WxH[@dx,dy] | set repeat stride=X,Y count=N | set residency resident|streamed | set bg_variant PART | set together F1 F2 | set zones S1 S2 | compose add PART DX DY | compose clear | frame NAME semantics flip_x --of OTHER | frame NAME origin X,Y | frame NAME dropped true --reason WHY | zone-remap SCENE 4=5")),
    }
    save_table(&mp, &t, out)?;
    out.emit(format!("{}: meta updated ({})", a.asset, w.join(" ")), json!({"file": mp.slash(), "changed": true}));
    Ok(())
}
